,(557,541),(638,541),(640,541),(649,541),(552,542),(552,543),(552,544),(552,545),(552,546),(552,547),(552,548),(552,549),(552,550),(552,551),(552,552),(552,553),(552,554),(552,555),(552,556),(552,557),(552,558),(552,559),(552,560),(552,561),(552,562),(552,563),(552,564),(553,565),(553,566),(553,567),(553,568),(553,569),(553,570),(553,571),(553,572),(553,573),(585,573),(555,574),(556,575),(556,576),(557,576),(556,577),(556,578),(556,579),(556,580),(556,581),(557,581),(557,582),(559,583),(585,583),(560,584),(561,584),(564,585),(574,585),(577,585),(578,585),(566,586),(567,587),(568,588),(569,589),(570,590),(570,591),(571,592),(572,593),(574,594),(575,595),(577,596),(578,597),(578,598),(578,599),(579,600),(580,600),(581,600),(579,601),(580,601),(581,601),(579,602),(580,602),(581,602),(579,603),(580,603),(581,603),(579,604),(580,604),(581,604),(579,605),(580,605),(581,605),(579,606),(580,606),(581,606),(579,607),(579,608),(579,609),(580,609),(581,609),(579,610),(580,610),(581,610),(579,611),(579,612),(579,613),(579,614),(580,614),(581,614),(579,615),(580,615),(581,615),(579,616),(580,616),(581,616),(580,617),(580,618),(581,618),(581,619),(582,620),(583,620),(582,621),(583,621),(585,621),(582,622),(583,622),(582,623),(583,623),(585,623),(582,624),(583,624),(585,624),(582,625),(583,625),(585,625),(582,626),(583,626),(585,626),(582,627),(583,627),(585,627),(582,628),(583,628),(582,629),(583,629),(585,629),(582,630),(583,630),(585,630),(582,631),(583,631),(585,631),(582,632),(583,632),(585,632),(585,633),(585,634),(585,635),(587,635),(585,636),(585,637),(587,637),(585,638),(587,638),(632,638),(649,638),(585,639),(585,640),(585,641),(585,642),(653,642),(585,643),(585,644),(587,645),(587,646),(589,647),(592,647),(593,647),(649,647),(590,648),(590,649),(593,650),(654,650),(655,650),(656,650),(593,651),(594,652),(594,653),(594,654),(594,655),(596,656),(596,657),(597,657),(602,657),(597,658),(598,659),(599,660),(600,660),(601,661),(602,662),(607,662),(602,663),(619,663),(620,663)