--
-- Table structure for table `article`
--

DROP TABLE IF EXISTS `article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `article` (
  `ID` bigint(20) unsigned NOT NULL COMMENT '标识',
  `company_id` bigint(20) unsigned NOT NULL COMMENT '诊所标识',
  `userid` bigint(20) unsigned NOT NULL COMMENT '发布人标识',
  `aricledate` datetime NOT NULL COMMENT '发布时间',
  `title` varchar(140) NOT NULL COMMENT '标题',
  `abstracts` text NOT NULL COMMENT '摘要',
  `content` mediumtext NOT NULL COMMENT '正文内容',
  `sources` text COMMENT '来源作者',
  `originallink` varchar(200) DEFAULT NULL COMMENT '原文链接',
  `create_by` varchar(65) NOT NULL COMMENT '创建人',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(65) DEFAULT NULL COMMENT '更新人',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `is_locked` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否启用（0：是；1：否）',
  `auditor` varchar(65) DEFAULT NULL COMMENT '审核人',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `auditordate` datetime DEFAULT NULL COMMENT '审核时间',
  `username` varchar(100) NOT NULL COMMENT '发布人名称',
  `auditstatus` varchar(2) NOT NULL DEFAULT '0' COMMENT '审核状态（0：待审核 1：通过 2：不通过）',
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='文章管理';
/*!40101 SET character_set_client = @saved_cs_client */;

