/*!40000 ALTER TABLE `article` DISABLE KEYS */;
INSERT INTO `article` VALUES (1403421434886168589,998324809623052308,998324809623052646,'2023-02-23 11:41:11','fsaf','fsaf','<p>fsafasf<img src=\"data:image/png;base64,\"></p>','fsaf','fsaff','诊所001管理员(17386700305)','2023-02-23 11:41:11','诊所001管理员(17386700305)','0','0','诊所管理员(17623478987)','2023-02-23 11:41:11','2023-02-23 11:41:25','诊所管理员','1'),(1403421452066038676,998324809623052308,998324809623052646,'2023-03-03 14:19:08','测试发布文章','测试阿斯蒂芬阿斯蒂芬邓烽大师傅','<p class=\"ql-align-center\"><strong>系统管理</strong></p><p class=\"ql-align-justify\">1、科室管理</p><p class=\"ql-align-justify\">【系统管理】—【科室管理】界面，按照科室名称、是否启用条件【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【科室管理主界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加科室界面，添加科室界面输入科室编号（必填）、科室名称（必填）、科室大类、地址、是否登记科室、默认登记科室、是否启用，【保存】按钮添加新科室，【取消】按钮取消添加科室。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加科室界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的科室信息类数据，通过勾选框选择和取消，【导出】按钮导出科室管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示数据】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出XLSX表格功能】</p><p>主科室信息操作列中有查看、编辑、复制、历史记录功能，【查看】科室维护的详细信息，【编辑】修改科室信息，【复制】相同的科室信息添加，【历史记录】察看科室创建修改的历史记录信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【察看科室信息】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【编辑修改科室】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加科室】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【科室历史记录】</p><p class=\"ql-align-justify\">2、角色管理</p><p class=\"ql-align-justify\">【系统管理】—【角色管理】界面，输入名称【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【角色管理界面】</p><p class=\"ql-align-justify\">点击【添加】按钮进入添加角色界面，输入代码（必填）、名称（必填），是否启用、备注信息内容点击【保存】按钮添加角色。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加角色】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的角色信息数据，通过勾选框选择和取消，【导出】按钮导出角色管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出角色数据】</p><p class=\"ql-align-justify\">角色信息的操作数据下有【查看】、【编辑】、【复制】、【权限】、【删除】、【历史记录】功能按钮，点击【查看】按钮查看角色信息，点击【编辑】按钮修改角色内容，点击【复制】按钮复制角色添加新角色，点击【权限】按钮进入权限设置界面勾选复选框给角色授权云诊所系统操作权限，点击【删除】按钮删除角色数据，点击【历史记录】按钮查看角色修改历史记录。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看角色信息】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【编辑修改角色信息】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【权限按钮设置角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【删除角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【角色历史修改记录】</p><p class=\"ql-align-justify\">3、用户管理</p><p class=\"ql-align-justify\">【系统管理】—【用户管理】界面，下拉框选择部门、输入用户名【搜索】按钮查询用户信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【用户管理主界面】</p><p class=\"ql-align-justify\">点击【添加】按钮打开添加用户界面，输入姓名（必填）、手机号（必填）、上传头像、证件类型、证件号码、科室（必填）、职位（必填）、类别（必填）、本诊所开始执业时间、本诊所结束执业时间、登录名自动获取手机号、是否启用、介绍数据点击【保存】按钮添加用户。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加用户界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的角色信息数据，通过勾选框选择和取消，【导出】按钮导出角色管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出用户数据】</p><p class=\"ql-align-justify\">用户信息的操作数据下有【查看】、【编辑】、【复制】、【删除】、【历史记录】功能按钮。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【操作中的查看、编辑、修改、删除、历史记录按钮】</p><p class=\"ql-align-justify\">点击【查看】按钮查看用户信息，查看用户界面中的编辑按钮可以进入修改用户界面修改用户数据。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看用户界面】</p><p class=\"ql-align-justify\">点击【编辑】按钮修改角色内容，修改完内容后点击保存按钮保存用户信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改用户界面】</p><p class=\"ql-align-justify\">点击【复制】按钮复制角色信息到添加用户界面，点击保存按钮添加用户信息。注意：手机号不能一样。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加界面】</p><p class=\"ql-align-justify\">点击【删除】按钮删除角色数据，点击确定删除角色。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【删除角色】</p><p class=\"ql-align-justify\">点击【历史记录】按钮查看用户登录和修改历史记录。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【历史记录】</p><p class=\"ql-align-justify\">4、诊疗项目</p><p class=\"ql-align-justify\">【系统管理】—【诊疗项目】界面，可以通过输入项目名称、选择项目类别、选择启用状态点击【搜索】按钮查询诊疗项目数据，【重置】按钮重置界面。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【诊疗项目主界面】</p><p>点击【添加】按钮进入添加诊疗项目界面，输入国家编码、项目名称（必填）、项目类型（必填）、项目类别、单位、成本价、销售价、是否启用、备注信息，点击【保存】按钮添加诊疗项目。注意项目类型分单次项目和组合项目，选择组合项目，需要在右侧诊疗子项目名称下拉框选择子项目，输入数量自动计算成本价和销售价。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加单项项目】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加组合项目】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】按钮，自定义查询显示的诊疗项目统计数据列，通过勾选框选择和取消，【导出】按钮导出诊疗管理界面搜索的数据为XLSX表格。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列设置】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【诊疗项目导出】</p><p>诊疗项目主界面操作列中有查看、编辑、复制、历史记录功能，【查看】诊疗项目的详细信息，【编辑】修改诊疗项目信息，【复制】相同的诊疗项目添加，【历史记录】察看诊疗项目创建修改的历史记录信息。</p><p>点击【查看】按钮进入查看诊疗项目界面，只能查看无法修改，可以点击编辑按钮进入修改诊疗项目界面</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看诊疗项目】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改诊疗项目】</p><p>点击【编辑按钮】进入修改诊疗项目界面，修改项目信息后点击【保存】按钮保存诊疗项目信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改诊疗项目】</p><p class=\"ql-align-justify\">点击【复制】按钮打开添加诊疗项目界面，复制选择的</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加诊疗项目】</p><p>点击【历史记录】按钮打开诊疗项目的创建和修改历史操作记录</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【历史记录】</p><p class=\"ql-align-justify\">5、慢病随访</p><p class=\"ql-align-justify\">【高血压患者随访】界面，输入随访信息点击提交。其中随访时间、症状、血压、下次目标、体重、下次目标、身高、体脂指数、心率、下次随访时间的数据内容是必填项。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【2型糖尿病患者随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【结核病随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【严重精神障碍患者随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【COPD随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【个人基本信息】界面填写基本信息数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【严重精神障碍服务知情同意书】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【中医体质辨识表】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\"><strong>会员管理</strong></p><p>&nbsp;</p><p>1、会员卡设置</p><p class=\"ql-align-justify\">【会员管理】—【会员卡设置】界面，按照会员卡名称、类型、是否启用、是否有效条件【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【会员卡设置主界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加会员卡界面，输入会员卡名称（必填）、会员卡张数（必填）、会员卡类型（必填）、有效时间、是否启用，录入体验项目：下拉框选择项目名称、输入项目数量，【添加体验项目】按钮可以增加新体验项目输入行，【保存】按钮添加会员卡。</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的会员卡数据，通过勾选框选择和取消，【导出】按钮导出会员卡设置界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出excel文件】</p><p>主会员卡设置界面操作列中有详细功能，【详情】按钮打开查看会员卡界面详细信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【详细查看会员卡界面】</p><p class=\"ql-align-justify\">查看会员卡界面有【编辑】按钮，点击【编辑】按钮进入修改会员卡界面</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改会员卡界面】</p><p>2、会员管理</p><p class=\"ql-align-justify\">【会员管理】—【会员管理】界面，按照姓名、会员卡号、状态、开卡日期、会员卡类型、会员卡名称条件【搜索】按钮查询会员卡信息，【重置】按钮重置界面信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【会员管理界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加会员界面，下拉框选择姓名（必选）、自动获取性别、身份证、电话信息，下拉框选择会员卡类型（必选）、会员卡名称（必选），卡号自动生成，【保存】按钮添加会员。</p><h4 class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\"><strong>&nbsp;</strong></h4><p class=\"ql-align-center\">【添加会员界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的会员数据，通过勾选框选择和取消，【导出】按钮导出会员管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出execl表格】</p><p>会员管理主界面操作列中有【详情】、【禁用】功能，【详情】按钮打开查看会员界面详细信息，点击【禁用】按钮禁用会员。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【详情查看会员信息】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【禁用会员操作】</p><p class=\"ql-align-center\"><strong>任务管理</strong></p><p>1、我的任务</p><p class=\"ql-align-justify\">【任务管理】—【我的任务】界面，按照任务名称、任务状态筛选【搜索】查询我的任务信息，【重置】按钮重置界面信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的任务数据，通过勾选框选择和取消，【导出】按钮导出我的任务界面搜索的数据为XLSX表格。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出Excel文件】</p><p>我的任务主界面操作列中有【立即执行】、【查看详情】功能，【立即执行】按钮执行任务，【查看详情】按钮打开查看发布的任务详细信息。</p><p>&nbsp;</p><p>点击【立即执行】按钮进入任务执行界面，在界面中显示机构发布的任务信息和附件信息，填写执行情况反馈信息执行进度待执行、已执行、附件上传、备注信息点击确定执行任务。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【立即执行界面】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看详情界面】</p><p>2、发布文章</p><p class=\"ql-align-justify\">【文章管理】—【发布文章】界面，按照截止时间范围、审核状态、文章标题筛选【搜索】查询发布文章信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">点击【添加】按钮打开</p><p class=\"ql-align-justify\">&nbsp;</p><p><img src=\"data:image/png;base64,\"></p>','测试','D:\\张烨\\定期病毒检查和系统更新\\2023年1月','诊所001管理员(17386700305)','2023-03-03 14:19:08','诊所001管理员(17386700305)','0','0',NULL,'2023-03-03 14:19:08',NULL,'诊所001管理员','0');
INSERT INTO `article` VALUES (1403421452066038677,998324809623052308,998324809623052646,'2023-03-03 14:19:10','测试发布文章','测试阿斯蒂芬阿斯蒂芬邓烽大师傅','<p class=\"ql-align-center\"><strong>系统管理</strong></p><p class=\"ql-align-justify\">1、科室管理</p><p class=\"ql-align-justify\">【系统管理】—【科室管理】界面，按照科室名称、是否启用条件【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【科室管理主界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加科室界面，添加科室界面输入科室编号（必填）、科室名称（必填）、科室大类、地址、是否登记科室、默认登记科室、是否启用，【保存】按钮添加新科室，【取消】按钮取消添加科室。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加科室界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的科室信息类数据，通过勾选框选择和取消，【导出】按钮导出科室管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示数据】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出XLSX表格功能】</p><p>主科室信息操作列中有查看、编辑、复制、历史记录功能，【查看】科室维护的详细信息，【编辑】修改科室信息，【复制】相同的科室信息添加，【历史记录】察看科室创建修改的历史记录信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【察看科室信息】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【编辑修改科室】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加科室】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【科室历史记录】</p><p class=\"ql-align-justify\">2、角色管理</p><p class=\"ql-align-justify\">【系统管理】—【角色管理】界面，输入名称【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【角色管理界面】</p><p class=\"ql-align-justify\">点击【添加】按钮进入添加角色界面，输入代码（必填）、名称（必填），是否启用、备注信息内容点击【保存】按钮添加角色。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加角色】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的角色信息数据，通过勾选框选择和取消，【导出】按钮导出角色管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出角色数据】</p><p class=\"ql-align-justify\">角色信息的操作数据下有【查看】、【编辑】、【复制】、【权限】、【删除】、【历史记录】功能按钮，点击【查看】按钮查看角色信息，点击【编辑】按钮修改角色内容，点击【复制】按钮复制角色添加新角色，点击【权限】按钮进入权限设置界面勾选复选框给角色授权云诊所系统操作权限，点击【删除】按钮删除角色数据，点击【历史记录】按钮查看角色修改历史记录。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看角色信息】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【编辑修改角色信息】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【权限按钮设置角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【删除角色】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【角色历史修改记录】</p><p class=\"ql-align-justify\">3、用户管理</p><p class=\"ql-align-justify\">【系统管理】—【用户管理】界面，下拉框选择部门、输入用户名【搜索】按钮查询用户信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【用户管理主界面】</p><p class=\"ql-align-justify\">点击【添加】按钮打开添加用户界面，输入姓名（必填）、手机号（必填）、上传头像、证件类型、证件号码、科室（必填）、职位（必填）、类别（必填）、本诊所开始执业时间、本诊所结束执业时间、登录名自动获取手机号、是否启用、介绍数据点击【保存】按钮添加用户。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加用户界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的角色信息数据，通过勾选框选择和取消，【导出】按钮导出角色管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出用户数据】</p><p class=\"ql-align-justify\">用户信息的操作数据下有【查看】、【编辑】、【复制】、【删除】、【历史记录】功能按钮。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【操作中的查看、编辑、修改、删除、历史记录按钮】</p><p class=\"ql-align-justify\">点击【查看】按钮查看用户信息，查看用户界面中的编辑按钮可以进入修改用户界面修改用户数据。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看用户界面】</p><p class=\"ql-align-justify\">点击【编辑】按钮修改角色内容，修改完内容后点击保存按钮保存用户信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改用户界面】</p><p class=\"ql-align-justify\">点击【复制】按钮复制角色信息到添加用户界面，点击保存按钮添加用户信息。注意：手机号不能一样。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加界面】</p><p class=\"ql-align-justify\">点击【删除】按钮删除角色数据，点击确定删除角色。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【删除角色】</p><p class=\"ql-align-justify\">点击【历史记录】按钮查看用户登录和修改历史记录。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【历史记录】</p><p class=\"ql-align-justify\">4、诊疗项目</p><p class=\"ql-align-justify\">【系统管理】—【诊疗项目】界面，可以通过输入项目名称、选择项目类别、选择启用状态点击【搜索】按钮查询诊疗项目数据，【重置】按钮重置界面。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【诊疗项目主界面】</p><p>点击【添加】按钮进入添加诊疗项目界面，输入国家编码、项目名称（必填）、项目类型（必填）、项目类别、单位、成本价、销售价、是否启用、备注信息，点击【保存】按钮添加诊疗项目。注意项目类型分单次项目和组合项目，选择组合项目，需要在右侧诊疗子项目名称下拉框选择子项目，输入数量自动计算成本价和销售价。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加单项项目】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【添加组合项目】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】按钮，自定义查询显示的诊疗项目统计数据列，通过勾选框选择和取消，【导出】按钮导出诊疗管理界面搜索的数据为XLSX表格。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列设置】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【诊疗项目导出】</p><p>诊疗项目主界面操作列中有查看、编辑、复制、历史记录功能，【查看】诊疗项目的详细信息，【编辑】修改诊疗项目信息，【复制】相同的诊疗项目添加，【历史记录】察看诊疗项目创建修改的历史记录信息。</p><p>点击【查看】按钮进入查看诊疗项目界面，只能查看无法修改，可以点击编辑按钮进入修改诊疗项目界面</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看诊疗项目】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改诊疗项目】</p><p>点击【编辑按钮】进入修改诊疗项目界面，修改项目信息后点击【保存】按钮保存诊疗项目信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改诊疗项目】</p><p class=\"ql-align-justify\">点击【复制】按钮打开添加诊疗项目界面，复制选择的</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【复制添加诊疗项目】</p><p>点击【历史记录】按钮打开诊疗项目的创建和修改历史操作记录</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【历史记录】</p><p class=\"ql-align-justify\">5、慢病随访</p><p class=\"ql-align-justify\">【高血压患者随访】界面，输入随访信息点击提交。其中随访时间、症状、血压、下次目标、体重、下次目标、身高、体脂指数、心率、下次随访时间的数据内容是必填项。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【2型糖尿病患者随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【结核病随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【严重精神障碍患者随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【COPD随访】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【个人基本信息】界面填写基本信息数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【严重精神障碍服务知情同意书】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><h4 class=\"ql-align-justify\">【中医体质辨识表】界面填写随访数据，点击提交按钮。</h4><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\"><strong>会员管理</strong></p><p>&nbsp;</p><p>1、会员卡设置</p><p class=\"ql-align-justify\">【会员管理】—【会员卡设置】界面，按照会员卡名称、类型、是否启用、是否有效条件【搜索】按钮查询科室信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【会员卡设置主界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加会员卡界面，输入会员卡名称（必填）、会员卡张数（必填）、会员卡类型（必填）、有效时间、是否启用，录入体验项目：下拉框选择项目名称、输入项目数量，【添加体验项目】按钮可以增加新体验项目输入行，【保存】按钮添加会员卡。</p><p class=\"ql-align-justify\">&nbsp;</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的会员卡数据，通过勾选框选择和取消，【导出】按钮导出会员卡设置界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出excel文件】</p><p>主会员卡设置界面操作列中有详细功能，【详情】按钮打开查看会员卡界面详细信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【详细查看会员卡界面】</p><p class=\"ql-align-justify\">查看会员卡界面有【编辑】按钮，点击【编辑】按钮进入修改会员卡界面</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【修改会员卡界面】</p><p>2、会员管理</p><p class=\"ql-align-justify\">【会员管理】—【会员管理】界面，按照姓名、会员卡号、状态、开卡日期、会员卡类型、会员卡名称条件【搜索】按钮查询会员卡信息，【重置】按钮重置界面信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【会员管理界面】</p><p class=\"ql-align-justify\">【添加】按钮进入添加会员界面，下拉框选择姓名（必选）、自动获取性别、身份证、电话信息，下拉框选择会员卡类型（必选）、会员卡名称（必选），卡号自动生成，【保存】按钮添加会员。</p><h4 class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\"><strong>&nbsp;</strong></h4><p class=\"ql-align-center\">【添加会员界面】</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的会员数据，通过勾选框选择和取消，【导出】按钮导出会员管理界面搜索的数据为XLSX表格。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p class=\"ql-align-center\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出execl表格】</p><p>会员管理主界面操作列中有【详情】、【禁用】功能，【详情】按钮打开查看会员界面详细信息，点击【禁用】按钮禁用会员。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【详情查看会员信息】</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【禁用会员操作】</p><p class=\"ql-align-center\"><strong>任务管理</strong></p><p>1、我的任务</p><p class=\"ql-align-justify\">【任务管理】—【我的任务】界面，按照任务名称、任务状态筛选【搜索】查询我的任务信息，【重置】按钮重置界面信息。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">主界面显示操作目录下有【自定义显示列】自定义查询显示的任务数据，通过勾选框选择和取消，【导出】按钮导出我的任务界面搜索的数据为XLSX表格。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【自定义显示列】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【导出Excel文件】</p><p>我的任务主界面操作列中有【立即执行】、【查看详情】功能，【立即执行】按钮执行任务，【查看详情】按钮打开查看发布的任务详细信息。</p><p>&nbsp;</p><p>点击【立即执行】按钮进入任务执行界面，在界面中显示机构发布的任务信息和附件信息，填写执行情况反馈信息执行进度待执行、已执行、附件上传、备注信息点击确定执行任务。</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【立即执行界面】</p><p><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-center\">【查看详情界面】</p><p>2、发布文章</p><p class=\"ql-align-justify\">【文章管理】—【发布文章】界面，按照截止时间范围、审核状态、文章标题筛选【搜索】查询发布文章信息，【重置】按钮重置界面信息。</p><p class=\"ql-align-justify\"><img src=\"//:0\" height=\"334\" width=\"553\">&nbsp;</p><p class=\"ql-align-justify\">点击【添加】按钮打开</p><p class=\"ql-align-justify\">&nbsp;</p><p><img src=\"data:image/png;base64,\"></p>','测试','D:\\张烨\\定期病毒检查和系统更新\\2023年1月','诊所001管理员(17386700305)','2023-03-03 14:19:10','诊所001管理员(17386700305)','0','0','诊所管理员(17623478987)','2023-03-03 14:19:10','2023-03-03 15:11:04','诊所管理员','2'),(1403421452066038688,998324809623052308,998324809623052646,'2023-03-03 14:25:05','测试','测试','<p>GET http://10.0.5.8:8186/api/Sys_Operator/Login?loginCode=admin&amp;password=123&amp;loginHospitalCode=1001&amp;loginDeptCode=0002 HTTP/1.1</p><p>Host: 10.0.5.8:8186</p><p>Connection: keep-alive</p><p>Accept: application/json, text/plain, */*</p><p>User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.0.0 Safari/537.36</p><p>Origin: http://10.0.5.8:8888</p><p>Referer: http://10.0.5.8:8888/</p><p>Accept-Encoding: gzip, deflate</p><p>Accept-Language: zh-CN,zh;q=0.9</p><p><br></p><p><br></p><p>HTTP/1.1 200 OK</p><p>Cache-Control: no-cache</p><p>Pragma: no-cache</p><p>Content-Length: 748</p><p>Content-Type: application/json; charset=utf-8</p><p>Expires: -1</p><p>Server: Microsoft-IIS/10.0</p><p>Access-Control-Allow-Origin: *</p><p>X-AspNet-Version: 4.0.30319</p><p>X-Powered-By: ASP.NET</p><p>Date: Wed, 22 Feb 2023 12:42:31 GMT</p><p><br></p><p>{\"Error\":\"\",\"Code\":0,\"Msg\":\"成功\",\"Token\":\"\",\"Data\":{\"Password\":\"\",\"UserStatus\":\"正常\",\"RoleName\":null,\"HospitalName\":null,\"LoginCode\":\"admin\",\"HospitalCode\":\"1001\",\"ManageHospital\":\"1001^西昌市人民医院\",\"ManageDept\":\"0002^消化内科,0021^门诊眼科\",\"HISOperCode\":\"admin\",\"HISOperID\":\"admin\",\"OperName\":\"超级管理员\",\"Pinyin\":\"admin\",\"DeptCode\":\"0002\",\"DeptName\":\"消化内科\",\"PersonStation\":\"医生\",\"TitleName\":\"副主任医生\",\"BloodOperCode\":\"\",\"Phone\":\"\",\"SortID\":0,\"SignImageID\":0,\"HeaderImageID\":5,\"IsUse\":true,\"Token\":\"974808e7f32e4c3a8d3eaf7ae1965562\",\"LoginHospitalCode\":\"1001\",\"LoginHospitalName\":\"西昌市人民医院\",\"LoginDeptCode\":\"0002\",\"LoginDeptName\":\"消化内科\",\"LoginWordCode\":\"\",\"LoginWordName\":\"\"}}</p>','','','诊所001管理员(17386700305)','2023-03-03 14:25:05','诊所001管理员(17386700305)','0','0','诊所管理员(17623478987)','2023-03-03 14:25:05','2023-03-03 15:10:52','诊所管理员','1'),(1440748067942823782,1403421469245907161,1403421469245907514,'2023-05-30 19:00:31','健康养生篇','健康日报','<p>健康养生很重要</p>','','','诊所管理员(18280312537)','2023-05-30 19:00:31','诊所管理员(18280312537)','0','0',NULL,'2023-05-30 19:00:31',NULL,'诊所管理员','0'),(1599292748405483285,1599292748405482497,1599292748405482816,'2023-07-05 11:52:23','医药篇|慢性病现状','1、介绍中国慢性病现状。\n2、心血管疾病（高血压、冠心病）情况分析\n3、糖尿病现状分析','<p>一、中国慢性病现状</p><p>慢性病属于病程长且通常情况下发展缓慢的疾病，具有患病人数多、医疗成本高、患病时间长以及服务需求大的特点，其中心血管疾病和糖尿病更是人类健康的头号杀手。根据弗若斯特沙利文的报告，2019年慢性病管理市场占中国医疗健康支出的比重已经达到了69.6%，而且未来也会继续增加。</p><p>图表1 慢性病市场及占比</p><p><span style=\"background-color: transparent;\"><img src=\"https://pic1.zhimg.com/80/v2-a681bbd477e19cbe3814a06cb23ae898_1440w.webp\" height=\"572\" width=\"1024\"></span></p><p>数据来源：弗若斯特沙利文、纵横市场公众号</p><p>根据《中国居民营养与慢性病状况报告（2020年）》，中国人口中，高血压患者达到4.2亿人；血脂异常人口有2亿人；糖尿病人口有1.21亿人，为全球第一。</p><p><em>【中国人慢病数据】</em></p><ol><li><em>超重及肥胖症人口：5.07亿（全球第一）高血压人口：4.2亿血脂异常：2亿高血脂：1亿糖尿病：1.21亿（全球第一）脂肪肝：1.2亿每天确诊癌症人数：1万</em></li></ol><p>为此，国家在不断为提升慢性病的知晓率、治疗率、控制率，降低死亡率的目标努力，实现慢性病的可防可控，致力于提升人们的健康水平。</p><p>图表2 中国慢性病防治中长期规划（2017—2025年）主要指标</p><p><span style=\"background-color: transparent;\"><img src=\"https://pic1.zhimg.com/80/v2-5c534eca42e84d9fe838e84f60751b60_1440w.webp\" height=\"626\" width=\"822\"></span></p><p>数据来源：国务院办公厅、纵横市场公众号</p><p><br></p><p><br></p><p>二、心血管疾病情况分析</p><p>累及心脏与血管的疾病称为心血管疾病，按照类型可以分为脑血管病、冠心病、高血压、心力衰竭、外周血管疾病、风湿性心脏病以及先天性心脏病。很多疾病都是由于不健康的饮食习惯和生活方式引起的，而且一但患病就很难根治，目前还是以药物治疗为主，患者平均年花费都在2万到3万之间。</p><p>图表3 心血管疾病分类</p><p><span style=\"background-color: transparent;\"><img src=\"https://pic2.zhimg.com/80/v2-fd9667c3c841ee6ea7b439eb6af53ae1_1440w.webp\" height=\"389\" width=\"1080\"></span></p><p>数据来源：WHO、纵横市场公众号</p><p>就高血压来说，发病因素包括：1、高钠、低钾膳食。2、超重和肥胖。3、过量饮酒。4、长期精神紧张。由于中国人生活习惯的改变以及压力的增加，高血压的患病率从1991年的7.7%增加到2015年27.9%。</p><p>图表4 我国六次高血压患病率调查结果</p><p><span style=\"background-color: transparent;\"><img src=\"https://pic1.zhimg.com/80/v2-279faa75ae20bd922ac1e305d27b4e00_1440w.webp\" height=\"250\" width=\"1080\"></span></p><p>数据来源：中国高血压防治指南、纵横市场公众号</p><p>但是由于医疗水平以及人们健康意识的提高，高血压知晓率、治疗率、控制率在不断提高。知晓率从1991年的27%提升到2015年的51.6%，治疗率从1991年的12%增加到2015年的45.8%，控制率从1991年的3%提升到2015年的16.8%。</p><p>图表5 199102015年高血压知晓率、治疗率和控制率</p><p><span style=\"background-color: transparent;\"><img src=\"https://pic4.zhimg.com/80/v2-64b0a4fd00006d08d778ad0359dd116f_1440w.webp\" height=\"318\" width=\"554\"></span></p><p>数据来源：中国心血管健康与疾病报告、纵横市场公众号</p><p>也就是说，国内高血压的市场规模=中国人人口*高血压患病率*知晓率*治疗率*人均花费。我们需要在降低高血压患病率和人均花费的同时，提升知晓率和治疗率，实现良性发展。</p><p>当前，抗高血压药物的发展相对成熟，根据机理大致可以分为五类：（1）利尿剂。优点是价格低、降压作用平稳，缺点是长期使用会导致低钾血症。（2）钙离子通道拮抗剂。优点是降压疗效和幅度较强、不影响血糖和血脂代谢，缺点是引起心率加快、面部潮红。（3）Beta受体拮抗剂。（4）血管紧张素转化酶抑制剂（ACEI），如普利类药物。优点是品种多、降压效果好，缺点是会引起刺激性干咳。（5）血管紧张素Ⅱ受体拮抗剂（ARB），如沙坦类药物。优点是比ACEI效果好，缺点是价格高。</p>','https://zhuanlan.zhihu.com/p/363443269','https://zhuanlan.zhihu.com/p/363443269','诊所管理员(17790275652)','2023-07-05 11:52:23','诊所管理员(17790275652)','0','0','诊所管理员(17790275651)','2023-07-05 11:52:23','2023-07-05 11:53:38','诊所管理员','1'),(1706615099144101169,1440748171022034255,1440748171022034608,'2023-09-19 21:24:21','高血压知识宣传','高血压知识宣传','<p>高血压知识宣传</p>','','','诊所管理员(17790275653)','2023-09-19 21:24:21','诊所管理员(17790275653)','0','0','诊所管理员(17790275651)','2023-09-19 21:24:21','2023-09-19 21:24:51','诊所管理员','1');
