--
-- Table structure for table `clinic_office`
--

DROP TABLE IF EXISTS `clinic_office`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `clinic_office` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `company_id` bigint(21) unsigned NOT NULL COMMENT '所属诊所',
  `code` varchar(64) NOT NULL COMMENT '科室编号',
  `name` varchar(128) NOT NULL COMMENT '科室名称',
  `sort` bigint(21) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `category` varchar(128) DEFAULT NULL COMMENT '科室大类',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `is_locked` varchar(1) NOT NULL DEFAULT '0' COMMENT '禁用（0：未禁用；1：禁用）',
  `is_default` varchar(1) DEFAULT NULL COMMENT '是否默认科室',
  `is_register` varchar(1) DEFAULT NULL COMMENT '是否为登记科室',
