--
-- Table structure for table `clinic_version`
--

DROP TABLE IF EXISTS `clinic_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `clinic_version` (
  `id` bigint(20) NOT NULL COMMENT '版本ID',
  `name` varchar(50) NOT NULL COMMENT '版本名称',
  `price` decimal(18,4) NOT NULL COMMENT '版本价格',
  `description` varchar(200) DEFAULT NULL COMMENT '版本描述',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `del_flag` bigint(21) unsigned NOT NULL COMMENT '删除标记',
  `role_id` bigint(21) unsigned NOT NULL DEFAULT '0' COMMENT '对应角色id',
  `code` varchar(100) NOT NULL DEFAULT '0' COMMENT '编码',
  `company_id` varchar(21) DEFAULT NULL COMMENT '公司id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `clinic_version_un` (`role_id`) USING BTREE,
  UNIQUE KEY `code_un` (`code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='诊所版本';
/*!40101 SET character_set_client = @saved_cs_client */;

