--
-- Table structure for table `cost_item`
--

DROP TABLE IF EXISTS `cost_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cost_item` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` bigint(21) NOT NULL COMMENT '诊所id',
  `item_code` varchar(64) NOT NULL COMMENT '项目编码',
  `item_country_code` varchar(64) DEFAULT NULL COMMENT '国家编码',
  `pinyin_code` varchar(64) NOT NULL COMMENT '拼音码',
  `item_name` varchar(64) NOT NULL COMMENT '项目名称',
  `item_type` varchar(64) DEFAULT NULL COMMENT '项目类别：检验（0），检查（1），理疗（2），治疗（3）',
  `unit` varchar(64) DEFAULT NULL COMMENT '单位：次（0），片（1）',
  `cost_price` decimal(18,4) DEFAULT '0.0000' COMMENT '成本价',
  `sale_price` decimal(18,4) DEFAULT '0.0000' COMMENT '销售价',
  `is_use` int(2) DEFAULT '1' COMMENT '是否启用',
  `is_deduct` int(2) DEFAULT '0' COMMENT '是否执行划扣：否（0），是（1）',
  `is_package` varchar(1) NOT NULL DEFAULT '0' COMMENT '是否为打包项目',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='费用项目';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `cost_item`
--

LOCK TABLES `cost_item` WRITE;
/*!40000 ALTER TABLE `cost_item` DISABLE KEYS */;
