--
-- Table structure for table `cost_item_package`
--

DROP TABLE IF EXISTS `cost_item_package`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cost_item_package` (
  `id` varchar(255) NOT NULL COMMENT '主键',
  `cost_item_id` varchar(255) DEFAULT NULL COMMENT '诊疗项目ID',
  `cost_item_pkg_id` varchar(255) NOT NULL COMMENT '诊疗项目套餐ID',
  `quantity` int(11) DEFAULT NULL COMMENT '数量',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `reference_unit` varchar(100) DEFAULT NULL COMMENT '参考单位',
  `reference_value` varchar(255) DEFAULT NULL COMMENT '参考值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='诊疗项目套餐明细表';
