--
-- Table structure for table `cure`
--

DROP TABLE IF EXISTS `cure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cure` (
  `id` bigint(20) NOT NULL,
  `company_id` bigint(20) NOT NULL COMMENT '诊所id',
  `recipel_detail_id` bigint(20) NOT NULL COMMENT '处方详情id',
  `executions` int(11) NOT NULL DEFAULT '0' COMMENT '执行进度',
  `create_by` varchar(100) NOT NULL COMMENT '操作人',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(100) NOT NULL COMMENT '修改人',
  `update_date` datetime NOT NULL COMMENT '修改时间',
  `del_type` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除字段0为未删，1为删除',
  `execute_date` datetime NOT NULL COMMENT '执行时间',
  `remarks` varchar(100) DEFAULT NULL COMMENT '备注',
  `add_number` int(11) DEFAULT NULL COMMENT '每次执行的次数',
  `recipel_info_id` bigint(20) DEFAULT NULL COMMENT '输液执行时的处方id',
  `infuse_group` int(11) DEFAULT NULL COMMENT '输液处方组数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

