--
-- Table structure for table `drug`
--

DROP TABLE IF EXISTS `drug`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `drug` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `goods_name` varchar(128) NOT NULL COMMENT '药品名称',
  `brand_name` varchar(128) DEFAULT NULL COMMENT '别名',
  `pinyin_code` varchar(64) DEFAULT NULL COMMENT '拼音码',
  `type` varchar(64) NOT NULL COMMENT '药品类型',
  `code` varchar(64) DEFAULT NULL COMMENT '药品编码',
  `source` varchar(128) DEFAULT NULL COMMENT '药品来源',
  `nature` varchar(64) DEFAULT NULL COMMENT '性质',
  `factory` varchar(64) DEFAULT NULL COMMENT '生产厂家',
  `standard_code` varchar(64) DEFAULT NULL COMMENT '国药准字',
  `bit_code` varchar(64) DEFAULT NULL COMMENT '本位码',
  `bar_code` varchar(64) DEFAULT NULL COMMENT '条形码',
  `insurance_code` varchar(64) DEFAULT NULL COMMENT '医保编码',
  `dosis` varchar(45) DEFAULT NULL COMMENT '剂量',
  `dosis_unit` varchar(64) DEFAULT NULL COMMENT '剂量单位',
  `preparation` varchar(45) DEFAULT NULL COMMENT '制剂',
  `preparation_unit` varchar(64) DEFAULT NULL COMMENT '制剂单位',
  `pack` varchar(64) DEFAULT NULL COMMENT '包装',
  `price` decimal(10,2) DEFAULT NULL COMMENT '售价',
  `is_unpack_sell` varchar(45) DEFAULT '0' COMMENT '允许拆零销售',
  `retail_price` decimal(10,4) DEFAULT NULL COMMENT '拆开后零售价',
  `status` varchar(1) NOT NULL COMMENT '启用标志',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `inventory` int(11) NOT NULL DEFAULT '0' COMMENT '库存',
  `western_medicine_use` varchar(255) DEFAULT NULL,
  `chinese_medicine_use` varchar(255) DEFAULT NULL,
  `single_dosage` int(11) DEFAULT NULL,
  `total` int(11) DEFAULT NULL,
  `max_no` int(11) DEFAULT '9999' COMMENT '单次最大使用量',
  `frequency` varchar(255) DEFAULT NULL,
  `days` varchar(255) DEFAULT NULL,
  `location_number` varchar(255) DEFAULT NULL COMMENT '货位号',
  `inventory_limit` varchar(255) DEFAULT NULL COMMENT '库存上限',
  `inventory_floor` varchar(255) DEFAULT NULL COMMENT '库存下限',
  `indate` varchar(255) DEFAULT NULL COMMENT '有效期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='药品信息';
/*!40101 SET character_set_client = @saved_cs_client */;

