--
-- Table structure for table `gen_table`
--

DROP TABLE IF EXISTS `gen_table`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `gen_table` (
  `id` bigint(20) unsigned NOT NULL COMMENT '标识',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `comments` varchar(64) DEFAULT NULL COMMENT '描述',
  `source` varchar(128) NOT NULL COMMENT '表来源',
  `class_name` varchar(128) NOT NULL COMMENT '实体类名称',
  `parent_table` bigint(20) unsigned DEFAULT NULL COMMENT '父表',
  `parent_table_fk` varchar(64) DEFAULT NULL COMMENT '关联父表外键',
  `is_association` varchar(1) NOT NULL DEFAULT '0' COMMENT '是关联表',
  `filter` varchar(2048) DEFAULT '' COMMENT '筛选条件',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `order_columns` varchar(2048) DEFAULT NULL COMMENT '排序字段',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='业务表';
/*!40101 SET character_set_client = @saved_cs_client */;

