--
-- Table structure for table `medicinal_storage_control`
--

DROP TABLE IF EXISTS `medicinal_storage_control`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `medicinal_storage_control` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `company_id` bigint(20) NOT NULL COMMENT '诊所ID',
  `storage_id` bigint(20) NOT NULL COMMENT '入库明细ID',
  `drug_stuff_id` bigint(20) NOT NULL COMMENT '药品/材料ID',
  `drug_stuff_name` varchar(255) NOT NULL COMMENT '药品/材料名称',
  `type` int(11) NOT NULL COMMENT '类型（1：药品；2：材料）',
  `storage_stock` decimal(24,4) NOT NULL DEFAULT '0.0000' COMMENT '入库总量',
  `used_stock` decimal(24,4) NOT NULL DEFAULT '0.0000' COMMENT '已使用库存数',
  `occupy_stock` decimal(24,4) NOT NULL DEFAULT '0.0000' COMMENT '当前占用库存数',
  `surplus_stock` decimal(24,4) NOT NULL DEFAULT '0.0000' COMMENT '剩余可用库存数',
  `reimburse_stock` decimal(24,4) NOT NULL DEFAULT '0.0000' COMMENT '报损库存数',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `return_todo_fee_stock` decimal(24,4) DEFAULT '0.0000' COMMENT '退药未退费量',
  `cancellation` varchar(1) DEFAULT '0' COMMENT '作废标记',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='药品/材料入库明细控制';
/*!40101 SET character_set_client = @saved_cs_client */;

