--
-- Table structure for table `org_department`
--

DROP TABLE IF EXISTS `org_department`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `org_department` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `company_id` bigint(21) unsigned NOT NULL COMMENT '公司',
  `code` varchar(64) NOT NULL COMMENT '编号',
  `parent_id` bigint(21) unsigned NOT NULL COMMENT '父级',
  `ids` varchar(2048) NOT NULL COMMENT '全标识',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `sort` bigint(21) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `director` bigint(21) unsigned DEFAULT NULL COMMENT '总监',
  `manager` bigint(21) unsigned DEFAULT NULL COMMENT '经理',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE,
  KEY `org_department_parent` (`parent_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='部门';
/*!40101 SET character_set_client = @saved_cs_client */;

