--
-- Table structure for table `patient`
--

DROP TABLE IF EXISTS `patient`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patient` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` varchar(45) DEFAULT NULL COMMENT '诊所id',
  `name` varchar(45) NOT NULL COMMENT '患者姓名',
  `gender` varchar(64) NOT NULL COMMENT '性别',
  `age` varchar(45) NOT NULL COMMENT '年龄',
  `month` varchar(45) NOT NULL COMMENT '月',
  `birthday` datetime DEFAULT NULL COMMENT '出生日期',
  `phone` varchar(45) NOT NULL COMMENT '联系方式',
  `card` varchar(45) NOT NULL COMMENT '身份证号',
  `with_patient_nexus` varchar(64) DEFAULT NULL COMMENT '与患者关系',
  `health_card_no` varchar(45) DEFAULT NULL COMMENT '健康卡号',
  `province` varchar(45) DEFAULT NULL COMMENT '省',
  `city` varchar(45) DEFAULT NULL COMMENT '市',
  `area` varchar(45) DEFAULT NULL COMMENT '区',
  `address` varchar(45) DEFAULT NULL COMMENT '详细地址',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `guardian_name` varchar(100) DEFAULT NULL COMMENT '监护人',
  `guardian_phone` varchar(100) DEFAULT NULL COMMENT '监护人电话',
  `open_id` varchar(255) DEFAULT NULL COMMENT '微信用户唯一标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='患者表';
/*!40101 SET character_set_client = @saved_cs_client */;

