--
-- Table structure for table `poor_households`
--

DROP TABLE IF EXISTS `poor_households`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `poor_households` (
  `id` int(11) NOT NULL COMMENT 'ID',
  `county` varchar(100) DEFAULT NULL COMMENT '县(市、区、旗)',
  `township` varchar(100) DEFAULT NULL COMMENT '乡(镇)',
  `
administrative_village` varchar(100) DEFAULT NULL COMMENT '行政村\r\n',
  `natural_village` varchar(100) DEFAULT NULL COMMENT '自然村\r\n',
  `name` varchar(10) DEFAULT NULL COMMENT '姓名\r\n',
  `number` varchar(18) DEFAULT NULL COMMENT '证件号码\r\n',
  `nation` varchar(10) DEFAULT NULL COMMENT '民族\r\n',
  `condition` varchar(20) DEFAULT NULL COMMENT '健康状况\r\n',
  `disability_category` varchar(20) DEFAULT NULL COMMENT '残疾类别\r\n',
  `disability_level` varchar(10) DEFAULT NULL COMMENT '残疾等级\r\n',
  `insure` varchar(10) DEFAULT NULL COMMENT '是否参加大病保险\r\n',
  `phone` bigint(20) DEFAULT NULL COMMENT '人联系电话\r\n',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='贫困户';
/*!40101 SET character_set_client = @saved_cs_client */;

