--
-- Table structure for table `recipel_detail`
--

DROP TABLE IF EXISTS `recipel_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `recipel_detail` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `recipel_info_id` bigint(21) DEFAULT NULL COMMENT '处方id',
  `drug_stuff_id` bigint(21) DEFAULT NULL COMMENT '药品材料id',
  `single_dosage` decimal(11,2) DEFAULT NULL COMMENT '单次用量',
  `total` int(11) DEFAULT '0' COMMENT '总量',
  `all_fee` decimal(10,2) DEFAULT NULL COMMENT '应付金额',
  `actual_payment` decimal(10,2) DEFAULT NULL COMMENT '实付金额',
  `western_medicine_use` varchar(64) DEFAULT NULL COMMENT '西药用法',
  `frequency` varchar(64) DEFAULT NULL COMMENT '频次用量',
  `days` varchar(64) DEFAULT NULL COMMENT '天数',
  `chinese_medicine_use` varchar(64) DEFAULT NULL COMMENT '中药用法',
  `infuse_use` varchar(64) DEFAULT NULL COMMENT '输液用法',
  `dripping_speed` varchar(45) DEFAULT NULL COMMENT '滴速',
  `skin_test` varchar(64) DEFAULT NULL COMMENT '皮试',
  `infuse_group` int(11) DEFAULT NULL COMMENT '组数',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '零售处方对应的处方类型',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `retail_type` varchar(1) DEFAULT NULL COMMENT '处方类型',
  `is_extra` int(11) DEFAULT NULL COMMENT '本条目是否是附加费',
  `seq` int(11) DEFAULT '0' COMMENT '显示顺序',
  `is_unpack_sell` int(11) NOT NULL COMMENT '是否拆零销售 0-否 1-是',
  `unit_price` decimal(24,4) DEFAULT NULL COMMENT '单价',
  `unit_type` varchar(100) DEFAULT NULL COMMENT '单价单位',
  `stuff_type` varchar(100) DEFAULT NULL COMMENT '物料类型：0-西药 1-中药  2-输液 3-诊疗项目  4-材料',
  `min_total` int(11) NOT NULL DEFAULT '0' COMMENT '最小单位总量',
  `trigger_type` varchar(1) DEFAULT '0' COMMENT '触发器状态',
  `executions` int(11) DEFAULT NULL COMMENT '执行进度',
  `infuse_type` int(11) NOT NULL DEFAULT '0' COMMENT '输液执行状态',
  `ststate` varchar(20) DEFAULT NULL COMMENT '皮试状态（0：未皮试，1：已皮试）',
  `stresult` varchar(20) DEFAULT NULL COMMENT '皮试结果（0：阴性，1：阳性）',
  `sttime` varchar(20) DEFAULT NULL COMMENT '皮试时间（分钟）',
  `stexecutetime` datetime DEFAULT NULL COMMENT '皮试执行时间',
  `stexecuteby` varchar(100) DEFAULT NULL COMMENT '皮试执行人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='处方详情';
/*!40101 SET character_set_client = @saved_cs_client */;

