--
-- Table structure for table `recipel_info`
--

DROP TABLE IF EXISTS `recipel_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `recipel_info` (
  `id` bigint(21) NOT NULL COMMENT '主键',
  `code` varchar(100) DEFAULT NULL COMMENT '处方编号',
  `name` varchar(100) DEFAULT NULL COMMENT '处方名称',
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `registration_id` bigint(20) DEFAULT NULL COMMENT '登记信息',
  `medical_record_id` bigint(21) DEFAULT NULL COMMENT '病历id',
  `recipel_type` varchar(64) DEFAULT NULL COMMENT '处方类别',
  `dosage` varchar(45) DEFAULT NULL COMMENT '剂量',
  `recipel_use` varchar(64) DEFAULT NULL COMMENT '用法',
  `frequency` varchar(64) DEFAULT NULL COMMENT '频次用量',
  `take_frequency` varchar(64) DEFAULT NULL COMMENT '服用频次',
  `single_dosage` int(11) DEFAULT NULL COMMENT '单次用量',
  `fee` decimal(10,2) DEFAULT NULL COMMENT '处方总价',
  `is_pay` varchar(1) DEFAULT '0' COMMENT '是否付款',
  `pay_date` datetime DEFAULT NULL COMMENT '付款时间',
  `is_dispension` varchar(1) DEFAULT NULL COMMENT '是否发药',
  `dispension_date` datetime DEFAULT NULL COMMENT '发药时间',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `seq` int(11) NOT NULL COMMENT '排序',
  `small_type` varchar(255) DEFAULT NULL COMMENT '小类小类【字典数据】',
  `entrust` varchar(4000) DEFAULT NULL COMMENT '医嘱',
  `status` int(11) DEFAULT NULL COMMENT '基本状态（1：开具完成；-1：  作废处方）',
  `charge_status` int(11) DEFAULT NULL COMMENT '收费状态（0：待收费；1：已收费 ；-1：已退费）',
  `dispension_status` int(11) DEFAULT NULL COMMENT '发药状态（0：待发药；1： 已发药 ；-1：已退药）',
  `retreat_charge_date` datetime DEFAULT NULL COMMENT '退费时间',
  `retreat_dispension_date` datetime DEFAULT NULL COMMENT '退药时间',
  `invalid_date` datetime DEFAULT NULL COMMENT '作废时间',
  `is_follow_up` int(11) NOT NULL DEFAULT '0' COMMENT '是否复诊处方',
  `follow_up_date` datetime DEFAULT NULL COMMENT '复诊时间',
  `pay_user` varchar(100) DEFAULT NULL COMMENT '付款操作人',
  `retreat_charge_user` varchar(100) DEFAULT NULL COMMENT '退费操作人',
  `retreat_dispension_user` varchar(100) DEFAULT NULL COMMENT '退药操作人',
  `dispension_user` varchar(100) DEFAULT NULL COMMENT '发药操作人',
  `retreat_date` datetime DEFAULT NULL COMMENT '退费时间',
  `dripping_speed` varchar(255) DEFAULT NULL,
  `infusion_day` varchar(255) DEFAULT NULL,
  `infusion_frequency` varchar(255) DEFAULT NULL,
  `infusion_use` varchar(255) DEFAULT NULL,
  `cure_type` int(11) NOT NULL DEFAULT '0' COMMENT '诊疗项目完成的标志，0为未完成，1为完成',
  `infuse_type` int(11) NOT NULL DEFAULT '0' COMMENT '输液执行状态',
