  `chiness_notes` varchar(255) DEFAULT NULL COMMENT '中药备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='处方信息';
