  `recipetemplate_id` bigint(21) DEFAULT NULL,
  `dosage` varchar(100) DEFAULT NULL COMMENT '剂量',
  `recipel_use` varchar(100) DEFAULT NULL COMMENT '用法',
  `frequency` varchar(100) DEFAULT NULL COMMENT '频次',
  `take_frequency` varchar(100) DEFAULT NULL COMMENT '服用',
