  `fee` decimal(10,2) DEFAULT NULL COMMENT '处方总价',
  `remarks` varchar(100) DEFAULT NULL COMMENT '备注信息',
  `small_type` varchar(100) DEFAULT NULL COMMENT '处方小类',
  `entrust` varchar(4000) DEFAULT NULL COMMENT '医嘱',
  `create_by` varchar(100) NOT NULL COMMENT '创建人',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(100) NOT NULL COMMENT '修改人',
  `update_date` datetime NOT NULL COMMENT '修改时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0:正常，1：删除）',
  `seq` int(11) DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='模板处方信息';
