--
-- Table structure for table `remote_diagnosis`
--

DROP TABLE IF EXISTS `remote_diagnosis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `remote_diagnosis` (
  `id` varchar(21) NOT NULL COMMENT '主键',
  `company_id` varchar(45) DEFAULT NULL COMMENT '诊所id',
  `registration_id` varchar(255) DEFAULT NULL COMMENT '挂号id',
  `patient_id` varchar(255) DEFAULT NULL COMMENT '患者id',
  `hospital_id` varchar(255) DEFAULT NULL COMMENT '申请医院id',
  `department_id` varchar(255) DEFAULT NULL COMMENT '申请科室id',
  `medic_id` varchar(255) DEFAULT NULL COMMENT '申请医生id',
  `name` varchar(255) DEFAULT NULL COMMENT '患者姓名',
  `gender` varchar(255) DEFAULT NULL COMMENT '患者性别',
  `card` varchar(255) DEFAULT NULL COMMENT '身份证号',
  `hospital` varchar(255) DEFAULT NULL COMMENT '申请医院',
  `department` varchar(255) DEFAULT NULL COMMENT '申请科室',
  `medic` varchar(255) DEFAULT NULL COMMENT '申请医生',
  `diagnosis_time` datetime DEFAULT NULL COMMENT '诊疗时间',
  `application_results` varchar(255) DEFAULT NULL COMMENT '申请结果',
  `status` varchar(255) DEFAULT NULL COMMENT '就诊状态(0:未提交, 1:待确认、2:就诊中、3:已结束、4:已发药、5:已退回)',
  `medication_status` varchar(255) DEFAULT NULL COMMENT '发药收费状态（0：代收费 1：已收费待发药 2：已发药）',
  `conference_id` varchar(255) DEFAULT NULL COMMENT '会议号',
  `recipient_name` varchar(255) DEFAULT NULL COMMENT '收件人姓名',
  `recipient_phone` varchar(255) DEFAULT NULL COMMENT '收件人电话',
  `province` varchar(255) DEFAULT NULL COMMENT '收件人所属省',
  `market` varchar(255) DEFAULT NULL COMMENT '收件人所属市',
  `distinguish` varchar(255) DEFAULT NULL COMMENT '收件人所属县/区',
  `apply_id` varchar(255) DEFAULT NULL COMMENT '远程申请流水号',
  `recipient_address` varchar(255) DEFAULT NULL COMMENT '收件人地址',
  `card_no` varchar(11) DEFAULT NULL COMMENT 'his就诊卡号',
  `order_no` varchar(11) DEFAULT NULL COMMENT '订单号',
  `pay_fee` varchar(255) DEFAULT NULL COMMENT '支付金额',
  `create_by` varchar(255) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(255) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(255) NOT NULL COMMENT '删除标记（0：正常 1：删除）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='远程诊疗记录';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `remote_diagnosis`
--

