DROP TABLE IF EXISTS `supplier_storage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `supplier_storage` (
  `id` bigint(21) NOT NULL,
  `company_id` bigint(21) DEFAULT NULL COMMENT '诊所id',
  `supplier_id` bigint(21) NOT NULL COMMENT '供应商id',
  `code` varchar(64) DEFAULT NULL COMMENT '入库单',
  `breed` int(11) DEFAULT NULL COMMENT '品种',
  `number` int(11) DEFAULT NULL COMMENT '数量',
  `all_bid` bigint(20) unsigned DEFAULT NULL COMMENT '总进价',
  `all_retail_price` decimal(10,4) DEFAULT NULL COMMENT '总零售价',
  `cancel_date` datetime DEFAULT NULL COMMENT '作废日期',
  `examine` varchar(64) DEFAULT NULL COMMENT '审核状态',
  `examine_date` datetime DEFAULT NULL COMMENT '审批时间',
  `with_goods_no` varchar(64) DEFAULT NULL COMMENT '随货单',
  `invoice_number` varchar(64) DEFAULT NULL COMMENT '发票号',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '入库人',
  `create_date` datetime NOT NULL COMMENT '入库时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `initial` int(11) DEFAULT NULL COMMENT '初始库存',
  `type` varchar(1) DEFAULT NULL COMMENT '入库类型（1：药品，2：材料）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='入库单';
