  `company_id` bigint(20) NOT NULL COMMENT '机构Id',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime DEFAULT NULL COMMENT ' 更新时间',
  `del_flag` varchar(1) DEFAULT '0' COMMENT '删除标记(0:正常；1:删除)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `sys_param_config_config_name_uindex` (`config_name`) USING BTREE,
  UNIQUE KEY `sys_param_config_id_uindex` (`id`) USING BTREE
