--
-- Table structure for table `sys_router`
--

DROP TABLE IF EXISTS `sys_router`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_router` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `code` varchar(64) DEFAULT NULL COMMENT '编号',
  `url` varchar(128) DEFAULT NULL COMMENT 'URL',
  `parent_id` bigint(21) unsigned NOT NULL COMMENT '父级',
  `ids` varchar(2048) NOT NULL COMMENT '全标识',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `sort` bigint(21) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `can_permission` varchar(1) NOT NULL DEFAULT '1' COMMENT '可以授权',
  `is_locked` varchar(1) NOT NULL DEFAULT '0' COMMENT '禁用',
  `properties` varchar(1024) NOT NULL COMMENT '扩展属性',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='路由';
/*!40101 SET character_set_client = @saved_cs_client */;

