DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_user` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `company_id` bigint(21) unsigned NOT NULL COMMENT '公司（0：超级管理员）',
  `department_id` bigint(21) unsigned DEFAULT NULL COMMENT '部门',
  `name` varchar(128) NOT NULL COMMENT '名称',
  `login_name` varchar(11) NOT NULL COMMENT '登录账号',
  `login_password` varchar(64) DEFAULT NULL COMMENT '密码',
  `is_locked` varchar(1) NOT NULL DEFAULT '0' COMMENT '禁用',
  `phone` varchar(20) NOT NULL COMMENT '手机号',
  `email` varchar(36) NOT NULL COMMENT '邮箱地址',
  `qy_open_id` varchar(100) DEFAULT NULL COMMENT '企业微信标识',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `is_admin` varchar(1) DEFAULT '0' COMMENT '是否是管理员（0：否；1：是）',
  `is_wxuser` varchar(1) DEFAULT '0' COMMENT '是否为微信用户',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE,
  KEY `department_id` (`department_id`) USING BTREE,
  KEY `idx_user_open_id` (`qy_open_id`) USING BTREE,
  KEY `sys_user_login_name` (`login_name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户';
/*!40101 SET character_set_client = @saved_cs_client */;

