DROP TABLE IF EXISTS `sys_user_ext`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sys_user_ext` (
  `id` bigint(21) unsigned NOT NULL COMMENT '标识',
  `user_id` bigint(21) unsigned NOT NULL COMMENT '用户',
  `photo_id` bigint(21) unsigned DEFAULT NULL COMMENT '照片',
  `is_duty` varchar(1) DEFAULT '0' COMMENT '是否在职（0：否；1：是）',
  `nation` varchar(12) DEFAULT NULL COMMENT '民族',
  `sex` varchar(10) DEFAULT NULL,
  `birthday` varchar(32) DEFAULT NULL COMMENT '生日',
  `credit_type` varchar(12) DEFAULT NULL COMMENT '证件类型',
  `credit_num` varchar(32) NOT NULL DEFAULT '0' COMMENT '证件号码',
  `post` varchar(20) NOT NULL COMMENT '职位',
  `job_type` varchar(20) DEFAULT NULL COMMENT '职业类型',
  `office` varchar(36) NOT NULL COMMENT '科室名称',
  `description` varchar(255) DEFAULT NULL COMMENT '描述信息',
  `start_work_time` varchar(100) DEFAULT NULL COMMENT '开始在诊所的日期',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `end_work_time` varchar(100) DEFAULT NULL COMMENT '结束在诊所的日期',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` varchar(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）',
  `company_id` bigint(21) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户拓展表';
/*!40101 SET character_set_client = @saved_cs_client */;

