  `taskmanagement_id` varchar(255) DEFAULT NULL COMMENT '任务管理id',
  `clinic_id` varchar(255) DEFAULT NULL COMMENT '诊所id',
  `userid` varchar(255) DEFAULT NULL COMMENT '执行人id',
  `del_flag` varchar(1) DEFAULT '0' COMMENT '删除标记（0：正常；1：删除）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='任务执行人';
